<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {safetyApi,labels,dateLabel,activePenalty,type ReportRow,type CaseDetail} from '@/api/moderation'
import {createRequestGuard} from '@/lib/requestGuard'
const status=ref('PENDING'),page=ref(0),items=ref<ReportRow[]>([]),total=ref(0),selected=ref<CaseDetail>(),features=ref<Record<string,string>>({})
const error=ref(''),loading=ref(false),busy=ref(false),decision=ref('WARNING'),reason=ref(''),duration=ref(24),unit=ref(60),chosen=ref<string[]>([])
const actionReasons=ref<Record<string,string>>({})
const queueGuard=createRequestGuard(),detailGuard=createRequestGuard();let alive=true
onBeforeUnmount(()=>{alive=false;queueGuard.cancel();detailGuard.cancel()})
async function load(){const check=queueGuard.start();loading.value=true;error.value='';try{const q=await safetyApi.queue(status.value,page.value,check.signal);if(check.current()){items.value=q.items;total.value=q.total;features.value=q.features}}catch(e){if(check.current())error.value=(e as Error).message}finally{if(check.current())loading.value=false}}
async function open(id:string){const check=detailGuard.start();selected.value=undefined;reason.value='';actionReasons.value={};chosen.value=[];decision.value='WARNING';duration.value=24;unit.value=60;error.value='';try{const data=await safetyApi.detail(id,check.signal);if(check.current())selected.value=data}catch(e){if(check.current())error.value=(e as Error).message}}
function filter(){page.value=0;void load()}
async function run(path:string,body:unknown){if(busy.value)return;const id=selected.value?.report.id;if(!id)return;busy.value=true;error.value='';try{await safetyApi.post(path,body);if(alive){await open(id);await load()}}catch(e){if(alive)error.value=(e as Error).message}finally{if(alive)busy.value=false}}
function review(){if(!selected.value)return;void run(`reports/${selected.value.report.id}/review`,{decision:decision.value,reason:reason.value,minutes:duration.value*unit.value,features:chosen.value})}
onMounted(load)
</script>
<template><div class="review-page"><header class="review-heading"><div><p class="page-kicker">MODERATION</p><h2>举报审核</h2><p>查看事实、填写理由，再决定是否处罚。每次处理都会留痕。</p></div><button class="button button--ghost" :disabled="loading||busy" @click="load">刷新列表</button></header><p v-if="error" class="form-error" role="alert">{{error}}</p><div class="review-layout"><aside class="review-queue"><label class="queue-filter">审核队列<select v-model="status" :disabled="busy" @change="filter"><option value="PENDING">待审核</option><option value="APPEALS">待处理申诉</option><option value="RESOLVED">已处理</option><option value="DISMISSED">已驳回</option><option value="ALL">全部记录</option></select></label><p class="queue-count">{{total}} 条记录 · 每页 25 条</p><p v-if="loading">正在读取…</p><p v-else-if="!items.length" class="review-empty">这里暂时没有举报。</p><button v-for="r in items" :key="r.id" class="case-row" :class="{chosen:selected?.report.id===r.id}" :disabled="busy" @click="open(r.id)"><span class="case-row-head"><b>{{r.target_name}}</b><em v-if="r.urgent">优先复核</em><small v-else>{{labels[r.status]}}</small></span><span class="case-reason">{{r.reason}}</span><span class="case-meta">{{labels[r.source_type]}} · {{dateLabel(r.created_at)}}</span></button><footer class="queue-pages"><button :disabled="page===0||busy||loading" @click="page--;load()">上一页</button><span>{{page+1}}</span><button :disabled="(page+1)*25>=total||busy||loading" @click="page++;load()">下一页</button></footer></aside><main class="case-main"><template v-if="selected"><header class="case-header"><p class="page-kicker">{{labels[selected.report.status]}} · {{labels[selected.report.source_type]}}</p><h3>{{selected.report.target_name}}</h3><code>{{selected.report.target_identity}}</code></header><section class="case-section"><h4>举报说明</h4><p class="preserve-text">{{selected.report.reason}}</p><h4>消息原文快照</h4><pre class="case-evidence">{{selected.report.evidence}}</pre><p v-if="selected.report.urgent" class="case-note">命中明确威胁规则。系统临时禁言最长 30 分钟，是否存在违规仍需人工确认。</p></section><form v-if="selected.report.status==='PENDING'" class="review-form case-section" @submit.prevent="review"><h4>审核决定</h4><label>处理方式<select v-model="decision" :disabled="busy"><option value="DISMISS">驳回举报</option><option value="WARNING">警告并结束审核</option><option value="MUTE">禁言</option><option value="FEATURE">限制指定功能</option><option value="BAN">封禁账号</option></select></label><fieldset v-if="decision==='FEATURE'"><legend>限制哪些功能</legend><label v-for="(label,key) in features" :key="key" class="feature-choice"><input v-model="chosen" type="checkbox" :value="key" :disabled="busy" />{{label}}</label></fieldset><div v-if="['MUTE','FEATURE','BAN'].includes(decision)" class="duration-row"><label>处罚时长<input v-model.number="duration" type="number" min="1" :max="Math.floor(525600/unit)" step="1" required :disabled="busy" /></label><label>单位<select v-model.number="unit" :disabled="busy"><option :value="1">分钟</option><option :value="60">小时</option><option :value="1440">天</option></select></label></div><label>审核理由<textarea v-model="reason" rows="4" required maxlength="1000" :disabled="busy" placeholder="说明认定事实、规则与处罚理由。用户会看到这段内容。" /></label><p class="case-note">禁言限制发送消息；封禁期间仅可查看处罚、申诉和退出。限时处罚到期自动解除。</p><button class="button button--dark" :disabled="busy||!reason.trim()||(decision==='FEATURE'&&!chosen.length)">{{busy?'保存中…':'确认审核决定'}}</button></form><section v-else class="case-section"><h4>审核结果</h4><p>{{selected.report.review_reason}}</p><small>{{dateLabel(selected.report.reviewed_at)}}</small></section><section v-if="selected.penalties.length" class="case-section"><h4>处罚与申诉</h4><article v-for="p in selected.penalties" :key="p.id" class="penalty-row"><header><b>{{labels[p.kind]}}</b><span>{{p.revoked_at?'已解除':activePenalty(p)?'生效中':'已到期'}}{{p.automatic?' · 临时处理':''}}</span></header><p>{{p.reason}}</p><p v-if="p.features">{{p.features.split(',').map(f=>features[f]||f).join('、')}}</p><small>截止 {{dateLabel(p.expires_at)}}</small><div v-if="p.appeal" class="appeal-text"><b>用户申诉</b><p>{{p.appeal}}</p><p v-if="p.appeal_reply">回复：{{p.appeal_reply}}</p></div><form v-if="!p.revoked_at || (p.appeal&&!p.appeal_reply)" @submit.prevent="run(`penalties/${p.id}/revoke`,{reason:actionReasons[p.id]})"><label>处理理由<textarea v-model="actionReasons[p.id]" rows="2" required maxlength="1000" :disabled="busy" /></label><div class="penalty-actions"><template v-if="p.appeal&&!p.appeal_reply"><button type="button" class="button button--ghost button--small" :disabled="busy||!actionReasons[p.id]?.trim()" @click="run(`penalties/${p.id}/decision`,{accept:false,reason:actionReasons[p.id]})">驳回申诉</button><button type="button" class="button button--dark button--small" :disabled="busy||!actionReasons[p.id]?.trim()" @click="run(`penalties/${p.id}/decision`,{accept:true,reason:actionReasons[p.id]})">接受申诉并解除</button></template><button v-else class="button button--ghost button--small" :disabled="busy||!actionReasons[p.id]?.trim()">提前解除处罚</button></div></form></article></section><details class="case-section"><summary>处理记录 · {{selected.events.length}}</summary><ol class="audit-list"><li v-for="e in selected.events" :key="e.id"><small>{{dateLabel(e.created_at)}} · {{e.actor_name||'系统'}}</small><p>{{e.detail}}</p></li></ol></details></template><div v-else class="review-empty"><h3>选择一条举报</h3><p>消息证据、处罚和申诉会显示在这里。</p></div></main></div></div></template>
<style scoped>
.review-page{max-width:1440px;margin:0 auto}.review-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:32px;gap:20px}.review-heading h2{margin:5px 0 12px}.review-heading p,.case-note,.queue-count{color:var(--muted);font-size:13px;line-height:1.8}.review-layout{display:grid;grid-template-columns:340px minmax(0,1fr);border:1px solid var(--line);border-radius:6px;min-height:650px;background:var(--paper);overflow:hidden}.review-queue{border-right:1px solid var(--line);padding:20px;background:var(--code-paper)}.queue-filter{display:flex;gap:12px;align-items:center;font-size:13px}.queue-filter select{flex:1}.queue-count{font-size:11px}.case-row{width:100%;text-align:left;padding:18px 12px;border:0;border-bottom:1px solid var(--line);background:transparent;color:var(--ink);cursor:pointer;border-radius:4px}.case-row:hover,.case-row.chosen{background:var(--paper);box-shadow:inset 3px 0 var(--green)}.case-row-head{display:flex;gap:12px;align-items:center}.case-row-head b{flex:1;font-weight:550}.case-row-head em{font-size:10px;color:#b55530;font-style:normal}.case-row-head small,.case-meta{color:var(--muted);font-size:10px}.case-reason{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;line-height:1.8;font-size:12px;margin:10px 0}.case-meta{display:block}.queue-pages{display:flex;align-items:center;justify-content:space-between;margin-top:24px}.queue-pages button{border:0;background:none;color:var(--green);cursor:pointer;font:inherit;font-size:12px}.case-main{padding:32px 40px;min-width:0}.case-header{padding-bottom:24px;border-bottom:1px solid var(--line)}.case-header h3{margin:8px 0 12px}.case-header code{font-size:11px;color:var(--muted);overflow-wrap:anywhere}.case-section{padding:24px 0;border-bottom:1px solid var(--line);font-size:13px;line-height:1.8}.case-section h4{font-size:14px;margin:0 0 12px;font-weight:600}.case-evidence{white-space:pre-wrap;overflow-wrap:anywhere;padding:20px;border-left:3px solid var(--line);background:var(--code-paper);font:inherit;max-height:320px;overflow:auto}.preserve-text{white-space:pre-wrap}.review-form label,.penalty-row form label{display:block;margin:16px 0;color:var(--ink)}select,input[type=number],textarea{font:inherit;color:var(--ink);background:var(--paper);border:1px solid var(--line);padding:10px 12px;border-radius:4px;max-width:100%}.review-form label>select,.review-form label>textarea,.penalty-row textarea{display:block;width:100%;margin-top:8px}textarea{resize:vertical}.duration-row{display:grid;grid-template-columns:1fr 1fr;gap:16px}.duration-row input{width:100%;margin-top:8px}.review-form fieldset{border:1px solid var(--line);padding:12px 16px}.review-form .feature-choice{display:inline-flex;gap:8px;margin:8px 18px 8px 0}.penalty-row{padding:18px 0;border-bottom:1px solid var(--line)}.penalty-row header{display:flex;justify-content:space-between}.penalty-row header span,.penalty-row small{color:var(--muted);font-size:11px}.penalty-actions{display:flex;gap:10px;justify-content:flex-end}.appeal-text{margin-top:16px;padding:14px;background:var(--code-paper);white-space:pre-wrap}.audit-list{padding-left:18px}.audit-list small{color:var(--muted);font-size:11px}.review-empty{padding:48px 16px;color:var(--muted);font-size:13px}.case-section summary{cursor:pointer}button:disabled{opacity:.45;cursor:default}select:focus-visible,textarea:focus-visible,input:focus-visible{outline:2px solid var(--green);outline-offset:2px}
</style>
